package ru.neverland.mintcontracts.procurement;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import ru.neverland.core.*;
public final class ProcurementAuditSmoke {
 public static void main(String[]args)throws Exception{
  var repo=new ProcurementRepository(Files.createTempDirectory("procurement-audit-").resolve("db.sqlite"));ProcurementSmoke.done(repo.ready());var quote=ProcurementSmoke.quote("town_hall");ProcurementSmoke.done(repo.quote(quote));ProcurementSmoke.done(repo.funding(quote.id()));
  var original=ProcurementSmoke.done(repo.auditPending()).get(0);ProcurementSmoke.check(original.kind().equals("CONTRACT_PAYMENT")&&original.actor().name().equals("Mayor"),"canonical funding intent creates immutable administrative evidence");
  var broken=new ProcurementAudit(repo,row->false,message->{});ProcurementSmoke.denied(()->ProcurementSmoke.done(broken.flush()),"failed administrative projection retains receipt");ProcurementSmoke.check(ProcurementSmoke.done(repo.auditPending()).get(0).equals(original),"retry retains exact ID and original timestamp");ProcurementSmoke.denied(()->ProcurementSmoke.done(broken.closeAsync()),"shutdown reports outstanding projection rather than dropping it");
  var enter=new CountDownLatch(1);var release=new CountDownLatch(1);var projected=new ArrayList<AuditRecord>();var audit=new ProcurementAudit(repo,row->{enter.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new AssertionError("audit gate");}catch(InterruptedException e){throw new RuntimeException(e);}projected.add(row);return true;},message->{});var flush=audit.flush();if(!enter.await(5,TimeUnit.SECONDS))throw new AssertionError("writer never entered");ProcurementSmoke.check(SuiteState.tryRun("procurement audit delayed",()->{}),"blocked administrative writer does not own SuiteState");ProcurementSmoke.check(ProcurementSmoke.done(repo.get(quote.id())).id().equals(quote.id()),"blocked administrative writer does not occupy SQLite worker");release.countDown();ProcurementSmoke.done(flush);ProcurementSmoke.check(ProcurementSmoke.done(repo.auditPending()).isEmpty()&&projected.equals(List.of(original)),"acknowledged exact receipt leaves durable outbox once");
  ProcurementSmoke.done(repo.bank(quote.id(),ProcurementSmoke.proof(quote,"PAID",false),false));var refund=ProcurementSmoke.done(repo.cancel(quote.id(),ProcurementSmoke.ACTOR,"Mayor",true));ProcurementSmoke.done(repo.bank(quote.id(),ProcurementSmoke.proof(refund,"PAID",true),true));var returned=ProcurementSmoke.done(repo.auditPending()).stream().filter(r->r.outcome().equals("PROCUREMENT_REFUNDED")).findFirst().orElseThrow();ProcurementSmoke.check(returned.from().type().equals("ESCROW")&&returned.to().type().equals("TOWN"),"refund administrative evidence points back to the city");
  ProcurementSmoke.done(audit.closeAsync());ProcurementSmoke.done(repo.closeAsync());
  var invalidPath=Files.createTempDirectory("procurement-never-opened-");var unopened=new ProcurementRepository(invalidPath);ProcurementSmoke.denied(()->ProcurementSmoke.done(unopened.ready()),"directory cannot become a ledger");var unopenedAudit=new ProcurementAudit(unopened,row->{throw new AssertionError("never initialized ledger cannot emit audit");},message->{});ProcurementSmoke.done(unopenedAudit.closeAsync());ProcurementSmoke.done(unopened.closeAsync());ProcurementSmoke.check(Files.isDirectory(invalidPath),"failed optional initialization closes workers and preserves original source");
  var drainedPath=Files.createTempDirectory("procurement-drain-").resolve("db.sqlite");var drained=new ProcurementRepository(drainedPath);ProcurementSmoke.done(drained.ready());var pending=new ArrayList<CompletionStage<?>>();var repeated=ProcurementSmoke.quote("forge");for(int i=0;i<64;i++)pending.add(drained.quote(repeated));var closing=drained.closeAsync();for(var future:pending)ProcurementSmoke.done(future);ProcurementSmoke.done(closing);ProcurementSmoke.check(!Files.exists(Path.of(drainedPath+"-wal"))&&!Files.exists(Path.of(drainedPath+"-shm")),"shutdown drains all accepted SQLite writes and closes both WAL files");
  System.out.println("ProcurementAuditSmoke PASS "+ProcurementSmoke.checks+" checks; failure, immutable retry, free Suite and SQL worker, durable ACK and refund direction");
 }
}
